def migrate_audit_stage(apps, schema_editor):
    """存量「待审核(audit)」改成「费用评审(cost_review)」。

    正式环节里没有审核这一步：原来的 audit 实际就是费用评审。
    阶段值同步改事件留痕的 from/to，否则时间轴会把老阶段显示成英文。
    """
    Project = apps.get_model('project', 'Project')
    ProjectEvent = apps.get_model('project', 'ProjectEvent')
    Project.objects.filter(stage='audit').update(stage='cost_review',
                                                 handler_role='auditor')
    ProjectEvent.objects.filter(from_stage='audit').update(from_stage='cost_review')
    ProjectEvent.objects.filter(to_stage='audit').update(to_stage='cost_review')


def seed_doc_templates(apps, schema_editor):
    """把三份文书模板挂进模板库，管理员可在「模板库」里替换。"""
    DocTemplate = apps.get_model('project', 'DocTemplate')
    seeds = [
        ('预审修正说明模板', 'precheck_notice', 'precheck',
         '初审后按规则预审与 AI 审查问题勾选生成的修正说明（函式）',
         'precheck_notice'),
        ('费用评审任务书模板', 'cost_review_task', 'cost_review',
         '委托财评机构评估可研与概算的任务书，评审期限默认 7 个自然日',
         'cost_review_task'),
        ('立项批复模板', 'approval_reply', 'approval',
         '财政审核同意后给申报单位的立项批复',
         'approval_reply'),
    ]
    for name, kind, stage, desc, key in seeds:
        DocTemplate.objects.get_or_create(
            kind=kind,
            defaults={'name': name, 'stage': stage, 'description': desc,
                      'builtin_key': key, 'active': True},
        )


